@tailwind base;
@tailwind components;
@tailwind utilities;

@import url('https://fonts.googleapis.com/css2?family=Abril+Fatface&family=Beth+Ellen&family=Comfortaa:wght@300;400;500;600;700&family=Roboto:ital,wght@0,100;0,300;0,400;0,500;0,700;0,900;1,100;1,300;1,400;1,500;1,700&family=Staatliches&display=swap');

:root {
  --color-primary: rgba(8, 7, 5, 1);
  --color-secondary: rgba(255, 1, 110, 1);
  --color-alternate: rgba(112, 5, 72, 1);
  --color-light: rgba(1, 255, 217, 1);
  --color-white: rgba(254, 248, 252, 1);
  --font-primary: 'Comfortaa', cursive;
  --font-secondary: 'Abril Fatface', cursive;
  --font-heading: 'Staatliches', cursive;
  --font-subheading: 'Beth Ellen', cursive;
}

* {
  scrollbar-color: var(--color-secondary)
}

/* Works on Chrome, Edge, and Safari */
*::-webkit-scrollbar {
  width: 14px;
}

*::-webkit-scrollbar-track {
  background: var(--color-primary);
}

*::-webkit-scrollbar-thumb {
  background: --color-secondary;
  border-radius: 20px;
  border: 3px solid --color-primary;
}

body {
  font-family: var(--font-primary);
  background: var(--color-primary);
  color: var(--color-white);
}

header {
  padding: 30px;

  h1 {
    font-family: var(--font-heading);
    font-size: 4vh;
  }
}

// Home
#line-1 {
  font-size: 3.2vh;

  #hello:hover::after {
    content: attr(data-tooltip);
  }
}

#name-home {
  font-size: 9vh;
}

#title-1,
#title-2 {
  font-size: 4.3vh;
}

#lead {
  font-size: 2vh;
  font-family: 'Beth Ellen', cursive;
}
